import torch,torch.nn as nn; exec("class Solution(nn.Module):\n    def __init__(self):\n        super().__init__()\n        torch.manual_seed(0)\n        self.fc1 = nn.Linear(784, 512)\n        self.relu = nn.ReLU()\n        self.dropout = nn.Dropout(0.2)\n        self.fc2 = nn.Linear(512, 10)\n        self.sigmoid = nn.Sigmoid()\n    def forward(self, images):\n        torch.manual_seed(0)\n        x = self.fc1(images)\n        x = self.relu(x)\n        x = self.dropout(x)\n        x = self.fc2(x)\n        x = self.sigmoid(x)\n        return x")